import type { Page } from '@playwright/test';

export async function createVideoFixture(page: Page) {
  await page.locator('body').click({ position: { x: 1, y: 1 } });
  const bytes = await page.evaluate(async () => { const canvas = document.createElement('canvas'); canvas.width = 320; canvas.height = 180; const context = canvas.getContext('2d')!; const videoStream = canvas.captureStream(30); const audioContext = new AudioContext(); await audioContext.resume(); const oscillator = audioContext.createOscillator(); const gain = audioContext.createGain(); const audioDestination = audioContext.createMediaStreamDestination(); oscillator.frequency.value = 440; gain.gain.value = 0.15; oscillator.connect(gain).connect(audioDestination); oscillator.start(); const stream = new MediaStream([...videoStream.getVideoTracks(), ...audioDestination.stream.getAudioTracks()]); const recorder = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp8,opus' }); const chunks: Blob[] = []; recorder.ondataavailable = event => chunks.push(event.data); recorder.start(); for (let frame = 0; frame < 24; frame++) { context.fillStyle = frame % 2 ? '#f59e0b' : '#18181b'; context.fillRect(0, 0, 320, 180); context.fillStyle = '#fff'; context.fillRect(frame * 10, 70, 30, 30); await new Promise(resolve => setTimeout(resolve, 34)); } const stopped = new Promise<void>((resolve, reject) => { recorder.onstop = () => resolve(); recorder.onerror = () => reject(new Error('無法建立含聲測試影片。')); }); recorder.stop(); await stopped; oscillator.stop(); await audioContext.close(); stream.getTracks().forEach(track => track.stop()); return Array.from(new Uint8Array(await new Blob(chunks, { type: 'video/webm' }).arrayBuffer())); });
  return Buffer.from(bytes);
}

export function createPulseWav() { const sampleRate = 8_000; const samples = new Int16Array(sampleRate); for (const second of [0.1, 0.5]) for (let index = 0; index < 80; index++) samples[Math.round(second * sampleRate) + index] = index < 40 ? 28_000 : -28_000; const buffer = Buffer.alloc(44 + samples.byteLength); buffer.write('RIFF', 0); buffer.writeUInt32LE(36 + samples.byteLength, 4); buffer.write('WAVEfmt ', 8); buffer.writeUInt32LE(16, 16); buffer.writeUInt16LE(1, 20); buffer.writeUInt16LE(1, 22); buffer.writeUInt32LE(sampleRate, 24); buffer.writeUInt32LE(sampleRate * 2, 28); buffer.writeUInt16LE(2, 32); buffer.writeUInt16LE(16, 34); buffer.write('data', 36); buffer.writeUInt32LE(samples.byteLength, 40); Buffer.from(samples.buffer).copy(buffer, 44); return buffer; }
